{
  "steps": [
    {
      "id": 1,
      "claim": "Einstein’s photo‑electric equation gives the maximum kinetic energy of emitted electrons as Kₘₐₓ = h·ν – φ.",
      "evidence": "Einstein (1905) derived Kₘₐₓ = hν – work‑function; confirmed experimentally.",
      "weight": 0.25,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "The stopping (retarding) potential Vₛ satisfies e·Vₛ = Kₘₐₓ.",
      "evidence": "By definition the stopping potential does exactly the electric work needed to cancel the maximum kinetic energy of the photoelectrons.",
      "weight": 0.20,
      "depends_on": [1]
    },
    {
      "id": 3,
      "claim": "Substituting Kₘₐₓ from step 1 into step 2 gives Vₛ = (h/e)·ν – φ/e.",
      "evidence": "Algebraic substitution and solving for Vₛ.",
      "weight": 0.20,
      "depends_on": [1, 2]
    },
    {
      "id": 4,
      "claim": "Introducing the threshold frequency ν₀ = φ/h rewrites the expression as Vₛ = (h/e)(ν – ν₀).",
      "evidence": "Definition of threshold frequency: photon energy equals work function when ν = ν₀.",
      "weight": 0.15,
      "depends_on": [3]
    },
    {
      "id": 5,
      "claim": "For frequencies ν > ν₀ the stopping potential is a linear function of ν with slope h/e and Vₛ = 0 at ν = ν₀.",
      "evidence": "Equation in step 4 is of the form y = mx + c; experimental data show a straight‑line V versus ν that passes through the origin at the threshold.",
      "weight": 0.15,
      "depends_on": [4]
    },
    {
      "id": 6,
      "claim": "Option (D) states exactly this linear relationship between the stopping potential and the frequency above the threshold frequency.",
      "evidence": "Option D wording matches the conclusion of step 5.",
      "weight": 0.05,
      "depends_on": [5]
    }
  ],
  "answer": "D",
  "confidence": 0.99,
  "considered": [
    {
      "answer": "A",
      "reason_rejected": "The work function φ is an intrinsic material constant; it does not vary with the incident light frequency."
    },
    {
      "answer": "B",
      "reason_rejected": "The work function is independent of wavelength; photon energy varies as 1/λ, not proportionally."
    },
    {
      "answer": "C",
      "reason_rejected": "Photocurrent depends on light intensity (number of photons), not linearly on wavelength."
    }
  ]
}
